/**
 * Generated by `createservice subscription.UpdateSubscriptionContextPaymentMethodService --type mutations`
 */
const dayjs = require('dayjs')
const get = require('lodash/get')
const isEmpty = require('lodash/isEmpty')

const { GQLError, GQLErrorCode: { BAD_USER_INPUT } } = require('@open-condo/keystone/errors')
const { getLogger } = require('@open-condo/keystone/logging')
const { GQLCustomSchema, getById, find } = require('@open-condo/keystone/schema')

const { NOT_FOUND } = require('@condo/domains/common/constants/errors')
const access = require('@condo/domains/subscription/access/UpdateSubscriptionContextPaymentMethodService')
const { SubscriptionPaymentAdapter } = require('@condo/domains/subscription/tasks/utils/SubscriptionPaymentAdapter')
const { SubscriptionContext } = require('@condo/domains/subscription/utils/serverSchema')
const { getSubscriptionPaymentRecipient } = require('@condo/domains/subscription/utils/serverSchema/getSubscriptionPaymentRecipient')

const logger = getLogger('UpdateSubscriptionContextPaymentMethodService')

/**
 * List of possible errors, that this custom schema can throw
 * They will be rendered in documentation section in GraphiQL for this custom schema
 */
const ERRORS = {
    SUBSCRIPTION_CONTEXT_NOT_FOUND: {
        mutation: 'updateSubscriptionContextPaymentMethod',
        variable: ['data', 'subscriptionContextId'],
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'SubscriptionContext not found',
    },
    SUBSCRIPTION_PAYMENT_RECIPIENT_NOT_CONFIGURED: {
        mutation: 'updateSubscriptionContextPaymentMethod',
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'SUBSCRIPTION_PAYMENT_RECIPIENT is not configured',
    },
    ACQUIRING_INTEGRATION_NOT_FOUND: {
        mutation: 'updateSubscriptionContextPaymentMethod',
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'AcquiringIntegrationContext not found for subscription payment recipient',
    },
}

const UpdateSubscriptionContextPaymentMethodService = new GQLCustomSchema('UpdateSubscriptionContextPaymentMethodService', {
    types: [
        {
            access: true,
            type: 'input UpdateSubscriptionContextPaymentMethodInput { dv: Int!, sender: SenderFieldInput!, subscriptionContext: SubscriptionContextWhereUniqueInput!, subscriptionContexts: [SubscriptionContextWhereUniqueInput!], bindingId: String }',
        },
        {
            access: true,
            type: 'type UpdateSubscriptionContextPaymentMethodOutput { id: String! }',
        },
    ],
    
    mutations: [
        {
            access: access.canUpdateSubscriptionContextPaymentMethod,
            schema: 'updateSubscriptionContextPaymentMethod(data: UpdateSubscriptionContextPaymentMethodInput!): UpdateSubscriptionContextPaymentMethodOutput',
            resolver: async (parent, args, context) => {
                const { data } = args
                const { subscriptionContext: subscriptionContextWhere, subscriptionContexts: explicitContextsWhere, bindingId, dv, sender } = data
                const subscriptionContextId = subscriptionContextWhere.id

                const subscriptionContext = await getById('SubscriptionContext', subscriptionContextId)
                if (!subscriptionContext || subscriptionContext.deletedAt) {
                    throw new GQLError(ERRORS.SUBSCRIPTION_CONTEXT_NOT_FOUND, context)
                }

                const organizationId = subscriptionContext.organization
                const invoiceId = subscriptionContext.invoice

                let targetContexts = [subscriptionContext]
                if (!isEmpty(explicitContextsWhere)) {
                    // The caller named the contexts to change, which is how a couple of features
                    // are dropped from a bundle without disturbing the plan they were bought with.
                    // Filtering by organization keeps a caller from reaching into someone else's bundle.
                    const explicitContextIds = explicitContextsWhere.map(({ id }) => id)
                    const foundContexts = await find('SubscriptionContext', {
                        id_in: explicitContextIds,
                        organization: { id: organizationId },
                        deletedAt: null,
                    })
                    if (foundContexts.length !== new Set(explicitContextIds).size) {
                        throw new GQLError(ERRORS.SUBSCRIPTION_CONTEXT_NOT_FOUND, context)
                    }
                    targetContexts = foundContexts
                } else if (invoiceId) {
                    const bundleContexts = await find('SubscriptionContext', {
                        invoice: { id: invoiceId },
                        deletedAt: null,
                    })
                    if (bundleContexts.length > 0) {
                        targetContexts = bundleContexts
                    }
                }

                const targetContextIds = targetContexts.map(ctx => ctx.id)
                const releasedBindingIds = new Set(
                    targetContexts.map(ctx => ctx.bindingId).filter(Boolean)
                )

                // Clearing the card is how a renewal is declined, and attaching one is how it is taken
                // back. Recorded separately so that an invoice-paid context, which has no card to
                // clear, still carries the decision into the next renewal
                const renewalCancelledAt = bindingId === null ? new Date().toISOString() : null

                for (const ctx of targetContexts) {
                    await SubscriptionContext.update(context, ctx.id, {
                        dv,
                        sender,
                        bindingId,
                        renewalCancelledAt,
                    })
                }

                if (bindingId === null && releasedBindingIds.size > 0) {
                    const { recipientOrgId: recipientOrganizationId, acquiringIntegration } = await getSubscriptionPaymentRecipient()
                    if (!recipientOrganizationId) {
                        throw new GQLError(ERRORS.SUBSCRIPTION_PAYMENT_RECIPIENT_NOT_CONFIGURED, context)
                    }
                    if (!acquiringIntegration) {
                        throw new GQLError(ERRORS.ACQUIRING_INTEGRATION_NOT_FOUND, context)
                    }

                    if (!acquiringIntegration.hostUrl) {
                        logger.warn({ msg: 'AcquiringIntegration missing hostUrl, skipping card token deletion', cardTokenIds: [...releasedBindingIds] })
                        return { id: subscriptionContextId }
                    }

                    for (const releasedBindingId of releasedBindingIds) {
                        const stillUsedContexts = await find('SubscriptionContext', {
                            organization: { id: organizationId },
                            bindingId: releasedBindingId,
                            id_not_in: targetContextIds,
                            endAt_gte: dayjs().format('YYYY-MM-DD'),
                            deletedAt: null,
                        })
                        if (stillUsedContexts.length > 0) continue

                        try {
                            await SubscriptionPaymentAdapter.deleteCardToken({
                                hostUrl: acquiringIntegration.hostUrl,
                                organizationId,
                                cardTokenId: releasedBindingId,
                            })
                            logger.info({ msg: 'Successfully deleted card token from payment gateway', cardTokenId: releasedBindingId })
                        } catch (error) {
                            const errorMessage = get(error, 'message') || 'Unknown error'
                            logger.error({ msg: 'Failed to delete card token from payment gateway', cardTokenId: releasedBindingId, error: errorMessage })
                        }
                    }
                }

                return {
                    id: subscriptionContextId,
                }
            },
        },
    ],
    
})

module.exports = {
    UpdateSubscriptionContextPaymentMethodService,
    ERRORS,
}
